   int n=Program.StrictInt(((IEnumerable)m["entityKey"]).Cast<object>().Last());var old=Obj(m,"captureBefore");var o=c.Observation();var fresh=Capture(o,n,expiry,c,Obj(old,"range"),old);var normalized=Clone(fresh);var a=Fields(old);var b=Fields(normalized);double error=0,directionError=0,magnitudeError=0;
